tool_schemas.implementation:
def get_figma_data(figma_file_key, snapshot_id=None, include_raw_document=None, include_derived_context=None, node_filters=None, nodes_limit=None, nodes_cursor=None, nodes_sort=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_figma_data"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def gen():
            ts = int(time.time() * 1000)
            b = ts.to_bytes(6, "big") + os.urandom(10)
            n = int.from_bytes(b, "big")
            out = []
            for _ in range(26):
                n, r = divmod(n, 32)
                out.append(alphabet[r])
            return prefix + "".join(reversed(out))
        return gen()

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(cur + pad).decode("utf-8")
            if not raw.startswith("o:"):
                return None
            off = int(raw.split(":", 1)[1])
            return off if off >= 0 else None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"o:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # usage/audit logging + rate limit
    reqlog_name = "request_logs.json"
    reqlog = _load(reqlog_name)
    if not isinstance(reqlog, list):
        reqlog = []

    now = datetime.datetime.utcnow()
    window_seconds = 60
    window_start = now - datetime.timedelta(seconds=window_seconds)
    recent = 0
    for r in reqlog[-2000:]:
        try:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            # parse simple ISO Z
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            if dt >= window_start:
                recent += 1
        except Exception:
            continue
    RATE_LIMIT_PER_MIN = 120
    if recent >= RATE_LIMIT_PER_MIN:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("RATE_LIMIT", "Too many requests. Please slow down.", limit_per_minute=RATE_LIMIT_PER_MIN)

    # validate inputs
    if not isinstance(figma_file_key, str) or not figma_file_key.strip():
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "figma_file_key must be a non-empty string.", field="figma_file_key")

    if snapshot_id is not None:
        if not isinstance(snapshot_id, str) or re.match(r"^fsnap_[0-9A-HJKMNP-TV-Z]{10,}$", snapshot_id) is None:
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("VALIDATION_ERROR", "snapshot_id must match ^fsnap_[0-9A-HJKMNP-TV-Z]{10,}$", field="snapshot_id")

    if include_raw_document is not None and not isinstance(include_raw_document, bool):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "include_raw_document must be a boolean.", field="include_raw_document")
    if include_derived_context is not None and not isinstance(include_derived_context, bool):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "include_derived_context must be a boolean.", field="include_derived_context")

    if nodes_limit is None:
        nodes_limit = 200
    if not isinstance(nodes_limit, int) or nodes_limit < 1 or nodes_limit > 1000:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "nodes_limit must be an integer between 1 and 1000.", field="nodes_limit")

    sort_enum = {"name_asc", "name_desc", "node_type_asc", "node_type_desc", "created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"}
    if nodes_sort is None:
        nodes_sort = "updated_at_desc"
    if not isinstance(nodes_sort, str) or nodes_sort not in sort_enum:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "nodes_sort must be one of the supported sort values.", field="nodes_sort", allowed=sorted(list(sort_enum)))

    off = _parse_cursor(nodes_cursor)
    if off is None:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "nodes_cursor is invalid.", field="nodes_cursor")

    allowed_node_types = {"DOCUMENT", "CANVAS", "FRAME", "GROUP", "SECTION", "COMPONENT", "COMPONENT_SET", "INSTANCE", "TEXT", "VECTOR", "STAR", "LINE", "ELLIPSE", "RECTANGLE", "POLYGON", "BOOLEAN_OPERATION", "SLICE", "STAMP", "WASHI_TAPE", "HIGHLIGHT", "EMBED", "LINK_UNFURL", "WIDGET", "IMAGE", "OTHER"}
    if node_filters is not None:
        if not isinstance(node_filters, dict):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("VALIDATION_ERROR", "node_filters must be an object.", field="node_filters")
        for k in node_filters.keys():
            if k not in {"node_types", "figma_node_ids", "parent_figma_node_id", "renderable_only", "visible_only", "text_search"}:
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("VALIDATION_ERROR", f"node_filters contains unsupported field '{k}'.", field="node_filters")
        if "node_types" in node_filters:
            v = node_filters["node_types"]
            if not isinstance(v, list) or any((not isinstance(x, str) or x not in allowed_node_types) for x in v):
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("VALIDATION_ERROR", "node_filters.node_types must be an array of valid node types.", field="node_filters.node_types")
        if "figma_node_ids" in node_filters:
            v = node_filters["figma_node_ids"]
            if not isinstance(v, list) or any((not isinstance(x, str) or not x) for x in v):
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("VALIDATION_ERROR", "node_filters.figma_node_ids must be an array of non-empty strings.", field="node_filters.figma_node_ids")
        if "parent_figma_node_id" in node_filters:
            v = node_filters["parent_figma_node_id"]
            if v is not None and (not isinstance(v, str) or not v):
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("VALIDATION_ERROR", "node_filters.parent_figma_node_id must be a non-empty string.", field="node_filters.parent_figma_node_id")
        if "renderable_only" in node_filters and node_filters["renderable_only"] is not None and not isinstance(node_filters["renderable_only"], bool):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("VALIDATION_ERROR", "node_filters.renderable_only must be a boolean.", field="node_filters.renderable_only")
        if "visible_only" in node_filters and node_filters["visible_only"] is not None and not isinstance(node_filters["visible_only"], bool):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("VALIDATION_ERROR", "node_filters.visible_only must be a boolean.", field="node_filters.visible_only")
        if "text_search" in node_filters:
            v = node_filters["text_search"]
            if v is not None and (not isinstance(v, str) or len(v) > 5000):
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("VALIDATION_ERROR", "node_filters.text_search must be a string.", field="node_filters.text_search")

    # load store
    files = _load("figma_files.json")
    snaps = _load("figma_file_snapshots.json")
    nodes = _load("figma_nodes.json")

    if not isinstance(files, list) or not isinstance(snaps, list) or not isinstance(nodes, list):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("CONFLICT", "Datastore is corrupted or in an unexpected format.")

    frow = None
    for f in files:
        if isinstance(f, dict) and f.get("figma_file_key") == figma_file_key:
            frow = f
            break
    if frow is None:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("NOT_FOUND", "Figma file not found.", figma_file_key=figma_file_key)

    if frow.get("status") == "needs_auth":
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "UNAUTHORIZED", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("UNAUTHORIZED", "Figma file requires authentication before it can be accessed.", figma_file_id=frow.get("id"))
    if frow.get("status") == "archived":
        # reads allowed, but no new snapshot creation
        pass

    # choose snapshot
    snap = None
    if snapshot_id is not None:
        for s in snaps:
            if isinstance(s, dict) and s.get("id") == snapshot_id:
                snap = s
                break
        if snap is None:
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("NOT_FOUND", "Snapshot not found.", snapshot_id=snapshot_id)
        if snap.get("figma_file_id") != frow.get("id"):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "UNAUTHORIZED", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("UNAUTHORIZED", "Snapshot does not belong to the specified file.", snapshot_id=snapshot_id)
    else:
        # latest ready snapshot by created_at then updated_at
        best = None
        def _dt(x):
            if not isinstance(x, str):
                return None
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("figma_file_id") != frow.get("id"):
                continue
            if s.get("status") != "ready":
                continue
            ca = _dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            ua = _dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            key = (ca, ua, s.get("id") or "")
            if best is None or key > best[0]:
                best = (key, s)
        if best is not None:
            snap = best[1]
        else:
            # none exists => create queued snapshot, unless archived
            if frow.get("status") == "archived":
                reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
                _save(reqlog_name, reqlog)
                return _err("NOT_FOUND", "No ready snapshot exists for this archived file.", figma_file_key=figma_file_key)
            # create
            sid = _ulid_like("fsnap_")
            ts = _now_iso()
            snap = {
                "id": sid,
                "figma_file_id": frow.get("id"),
                "figma_version": None,
                "document_etag": None,
                "raw_document": None,
                "derived_context": None,
                "node_count": 0,
                "status": "queued",
                "build_started_at": None,
                "build_completed_at": None,
                "error": None,
                "created_at": ts,
                "updated_at": ts,
            }
            snaps.append(snap)
            _save("figma_file_snapshots.json", snaps)

    # nodes list
    snap_id = snap.get("id")
    snap_nodes = [n for n in nodes if isinstance(n, dict) and n.get("snapshot_id") == snap_id]

    # filter
    if node_filters:
        if "node_types" in node_filters and node_filters["node_types"]:
            sset = set(node_filters["node_types"])
            snap_nodes = [n for n in snap_nodes if n.get("node_type") in sset]
        if "figma_node_ids" in node_filters and node_filters["figma_node_ids"]:
            sset = set(node_filters["figma_node_ids"])
            snap_nodes = [n for n in snap_nodes if n.get("figma_node_id") in sset]
        if "parent_figma_node_id" in node_filters and node_filters["parent_figma_node_id"] is not None:
            pid = node_filters["parent_figma_node_id"]
            snap_nodes = [n for n in snap_nodes if n.get("parent_figma_node_id") == pid]
        if node_filters.get("renderable_only") is True:
            snap_nodes = [n for n in snap_nodes if n.get("renderable") is True]
        if node_filters.get("visible_only") is True:
            snap_nodes = [n for n in snap_nodes if n.get("is_visible") is True]
        if node_filters.get("text_search"):
            q = node_filters["text_search"].lower()
            def _txt(n):
                a = n.get("name") or ""
                b = n.get("text_content") or ""
                return (str(a) + " " + str(b)).lower()
            snap_nodes = [n for n in snap_nodes if q in _txt(n)]

    # sort
    def _k(n, field):
        v = n.get(field)
        if field in ("created_at", "updated_at"):
            if isinstance(v, str):
                return v
            return ""
        if v is None:
            return ""
        return str(v).lower() if isinstance(v, str) else v

    reverse = False
    sort_field = None
    if nodes_sort.endswith("_desc"):
        reverse = True
    if nodes_sort.startswith("name_"):
        sort_field = "name"
    elif nodes_sort.startswith("node_type_"):
        sort_field = "node_type"
    elif nodes_sort.startswith("created_at_"):
        sort_field = "created_at"
    elif nodes_sort.startswith("updated_at_"):
        sort_field = "updated_at"

    snap_nodes.sort(key=lambda n: (_k(n, sort_field), n.get("figma_node_id") or "", n.get("id") or ""), reverse=reverse)

    total = len(snap_nodes)
    page = snap_nodes[off: off + nodes_limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    # build response
    snapshot_out = dict(snap)
    if not (include_raw_document is True):
        snapshot_out.pop("raw_document", None)
    if not (include_derived_context is True):
        snapshot_out.pop("derived_context", None)

    resp = {
        "figma_file": dict(frow),
        "snapshot": snapshot_out,
        "nodes": page,
        "nodes_paging": {"total": total, "limit": nodes_limit, "cursor": nodes_cursor, "next_cursor": next_cursor, "has_more": has_more},
    }

    reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "figma_file_id": frow.get("id"), "snapshot_id": snap_id})
    _save(reqlog_name, reqlog)
    return resp

def download_figma_images(figma_file_key, snapshot_id=None, figma_node_ids=None, formats=None, scale=None, use_absolute_bounds=None, render_job_id=None, wait_for_completion=None, assets_limit=None, assets_cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "download_figma_images"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt_parse(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        # ULID-like, 26 chars base32 crockford, deterministic-enough for local store
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        b = ts.to_bytes(6, "big") + os.urandom(10)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out))

    def _reqlog(status, latency_ms, extra=None):
        # best-effort observable dynamics
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("rlog_"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # simple per-endpoint rate limit: 120/min; enforce via request_logs
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != endpoint:
                continue
            dt = _dt_parse(r.get("timestamp"))
            if dt and dt >= window:
                cnt += 1
        if cnt >= 120:
            return False, _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", retry_after_seconds=60)
        return True, None

    ok, rlerr = _rate_limit_check()
    if not ok:
        _reqlog("rate_limited", (time.time() - t0) * 1000)
        return rlerr

    # ---- input validation (relaxed where tool schema allows opaque cursor) ----
    if not isinstance(figma_file_key, str) or not figma_file_key.strip():
        _reqlog("validation_error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "figma_file_key is required.", field="figma_file_key")

    if snapshot_id is not None:
        if not isinstance(snapshot_id, str):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "snapshot_id must be a string.", field="snapshot_id")
        # keep vendor pattern, but don't over-reject if it doesn't match; accept if it exists in store
        if not re.match(r"^fsnap_[0-9A-HJKMNP-TV-Z]{10,}$", snapshot_id):
            # allow, but will have to exist as FK later
            pass

    if render_job_id is not None:
        if not isinstance(render_job_id, str):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "render_job_id must be a string.", field="render_job_id")
        if not re.match(r"^firj_[0-9A-HJKMNP-TV-Z]{10,}$", render_job_id):
            # allow if it exists in store
            pass

    if figma_node_ids is not None:
        if not isinstance(figma_node_ids, list) or len(figma_node_ids) < 1 or any(not isinstance(x, str) or not x for x in figma_node_ids):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "figma_node_ids must be a non-empty array of strings.", field="figma_node_ids")

    if formats is not None:
        if not isinstance(formats, list) or len(formats) < 1 or any(not isinstance(x, str) for x in formats):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "formats must be a non-empty array.", field="formats")
        allowed = {"svg", "png"}
        bad = [x for x in formats if x not in allowed]
        if bad:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "formats contains invalid values.", field="formats", invalid=bad)

    if scale is not None:
        if not isinstance(scale, (int, float)):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "scale must be a number.", field="scale")
        # accept tool schema 0.01..10 (relaxed from datastore 0.1..4.0; we will clamp for job persistence if needed)
        if scale < 0.01 or scale > 10:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "scale out of range.", field="scale", min=0.01, max=10)

    if use_absolute_bounds is not None and not isinstance(use_absolute_bounds, bool):
        _reqlog("validation_error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "use_absolute_bounds must be boolean.", field="use_absolute_bounds")

    if wait_for_completion is not None and not isinstance(wait_for_completion, bool):
        _reqlog("validation_error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "wait_for_completion must be boolean.", field="wait_for_completion")

    if assets_limit is not None:
        if not isinstance(assets_limit, int):
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "assets_limit must be an integer.", field="assets_limit")
        if assets_limit < 1 or assets_limit > 1000:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "assets_limit out of range.", field="assets_limit", min=1, max=1000)

    # assets_cursor is opaque: accept any string, including those that look like ids.
    if assets_cursor is not None and not isinstance(assets_cursor, str):
        _reqlog("validation_error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "assets_cursor must be a string.", field="assets_cursor")

    # ---- load collections ----
    files = _load("figma_files.json")
    snaps = _load("figma_file_snapshots.json")
    nodes = _load("figma_nodes.json")
    jobs = _load("figma_image_render_jobs.json")
    assets = _load("figma_rendered_assets.json")

    if not isinstance(files, list): files = []
    if not isinstance(snaps, list): snaps = []
    if not isinstance(nodes, list): nodes = []
    if not isinstance(jobs, list): jobs = []
    if not isinstance(assets, list): assets = []

    # resolve file context; do not fail if some rows missing; search a workable one
    file_row = None
    for f in files:
        if f.get("figma_file_key") == figma_file_key:
            file_row = f
            break
    if file_row is None:
        _reqlog("not_found", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Figma file key not found.", field="figma_file_key")

    if file_row.get("status") == "needs_auth":
        _reqlog("unauthorized", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "File requires authentication before rendering.", figma_file_key=figma_file_key)

    if file_row.get("status") == "archived":
        # allow reads of existing job/assets; but prevent creation
        if render_job_id is None:
            _reqlog("invalid_transition", (time.time() - t0) * 1000)
            return _err("INVALID_TRANSITION", "File is archived; cannot create new render jobs.", figma_file_key=figma_file_key)

    figma_file_id = file_row.get("id")

    # helper: find latest ready snapshot for file
    def _latest_ready_snapshot_id():
        latest = None
        latest_dt = None
        for s in snaps:
            if s.get("figma_file_id") != figma_file_id:
                continue
            if s.get("status") != "ready":
                continue
            dt = _dt_parse(s.get("build_completed_at")) or _dt_parse(s.get("updated_at")) or _dt_parse(s.get("created_at"))
            if latest is None or (dt and (latest_dt is None or dt > latest_dt)):
                latest = s
                latest_dt = dt
        return latest.get("id") if latest else None

    # ---- job lookup or creation ----
    job_row = None
    created_job = False

    if render_job_id is not None:
        for j in jobs:
            if j.get("id") == render_job_id:
                job_row = j
                break
        if job_row is None:
            _reqlog("not_found", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Render job not found.", field="render_job_id")

        # enforce job belongs to this file
        if job_row.get("figma_file_id") != figma_file_id:
            _reqlog("unauthorized", (time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "Render job does not belong to requested file.", render_job_id=render_job_id)

    else:
        # Creating a new job requires figma_node_ids + formats
        if figma_node_ids is None or formats is None:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "figma_node_ids and formats are required when creating a render job.", field="figma_node_ids")

        if len(figma_node_ids) < 1 or len(figma_node_ids) > 500:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "figma_node_ids length must be between 1 and 500.", field="figma_node_ids", min=1, max=500)

        # choose snapshot
        chosen_snapshot_id = snapshot_id or _latest_ready_snapshot_id()
        if chosen_snapshot_id is None:
            _reqlog("NOT_FOUND", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "No ready snapshot available for this file.", figma_file_key=figma_file_key)

        # validate snapshot exists and belongs to file
        snap_row = None
        for s in snaps:
            if s.get("id") == chosen_snapshot_id:
                snap_row = s
                break
        if snap_row is None:
            _reqlog("not_found", (time.time() - t0) * 1000)
            return _err("NOT_FOUND", "snapshot_id not found.", field="snapshot_id")
        if snap_row.get("figma_file_id") != figma_file_id:
            _reqlog("validation_error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "snapshot_id does not belong to figma_file_key.", field="snapshot_id")
        if snap_row.get("status") != "ready":
            _reqlog("invalid_transition", (time.time() - t0) * 1000)
            return _err("INVALID_TRANSITION", "Snapshot is not ready for rendering.", snapshot_id=chosen_snapshot_id, status=snap_row.get("status"))

        # default boolean
        if use_absolute_bounds is None:
            use_absolute_bounds = False

        # Persist job using datastore constraints for scale: must be null or 0.1..4.0
        job_scale = scale
        if job_scale is not None:
            if job_scale < 0.1:
                job_scale = 0.1
            if job_scale > 4.0:
                job_scale = 4.0

        now_iso = _now_iso()
        job_row = {
            "id": _gen_id("firj_"),
            "figma_file_id": figma_file_id,
            "snapshot_id": chosen_snapshot_id,
            "requested_node_ids": list(figma_node_ids),
            "formats": list(formats),
            "scale": job_scale,
            "use_absolute_bounds": bool(use_absolute_bounds),
            "status": "queued",
            "requested_at": now_iso,
            "completed_at": None,
            "error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job_row)
        _save("figma_image_render_jobs.json", jobs)
        created_job = True

        # Create/upsert assets rows according to renderability/visibility rules in referenced snapshot
        snap_nodes = {}
        for n in nodes:
            if n.get("snapshot_id") == chosen_snapshot_id:
                snap_nodes[n.get("figma_node_id")] = n

        # de-dup within request
        req_node_ids = []
        seen = set()
        for nid in figma_node_ids:
            if nid not in seen:
                seen.add(nid)
                req_node_ids.append(nid)

        def _asset_key(render_job_id_v, figma_node_id_v, fmt_v, scale_v):
            return (render_job_id_v, figma_node_id_v, fmt_v, 0 if scale_v is None else float(scale_v))

        existing_index = {}
        for a in assets:
            existing_index[_asset_key(a.get("render_job_id"), a.get("figma_node_id"), a.get("format"), a.get("scale"))] = a

        for nid in req_node_ids:
            node_row = snap_nodes.get(nid)
            render_ok = False
            reason = None
            if node_row is None:
                render_ok = False
                reason = "Node not found in snapshot."
            else:
                if not bool(node_row.get("is_visible")):
                    render_ok = False
                    reason = "Node is not visible."
                elif not bool(node_row.get("renderable")):
                    render_ok = False
                    reason = "Node is not renderable."
                else:
                    render_ok = True

            for fmt in formats:
                a_scale = job_scale if fmt == "png" else None
                k = _asset_key(job_row["id"], nid, fmt, a_scale)
                if k in existing_index:
                    # idempotent: do not create duplicates
                    continue

                now_iso2 = _now_iso()
                if render_ok:
                    # produce a plausible available asset
                    ct = "image/svg+xml" if fmt == "svg" else "image/png"
                    # time-limited figma_cdn url
                    exp = datetime.datetime.utcnow() + datetime.timedelta(hours=1)
                    asset_row = {
                        "id": _gen_id("fasset_"),
                        "render_job_id": job_row["id"],
                        "figma_file_id": figma_file_id,
                        "snapshot_id": chosen_snapshot_id,
                        "figma_node_id": nid,
                        "format": fmt,
                        "scale": a_scale,
                        "content_type": ct,
                        "byte_size": None,
                        "storage_provider": "figma_cdn",
                        "storage_key": None,
                        "source_url": f"https://cdn.figma.com/render/{figma_file_key}/{nid}.{fmt}",
                        "source_url_expires_at": exp.replace(microsecond=0).isoformat() + "Z",
                        "status": "available",
                        "error": None,
                        "created_at": now_iso2,
                        "updated_at": now_iso2,
                    }
                else:
                    asset_row = {
                        "id": _gen_id("fasset_"),
                        "render_job_id": job_row["id"],
                        "figma_file_id": figma_file_id,
                        "snapshot_id": chosen_snapshot_id,
                        "figma_node_id": nid,
                        "format": fmt,
                        "scale": a_scale,
                        "content_type": None,
                        "byte_size": None,
                        "storage_provider": "figma_cdn",
                        "storage_key": None,
                        "source_url": None,
                        "source_url_expires_at": None,
                        "status": "error",
                        "error": {"code": "NOT_RENDERABLE", "message": reason},
                        "created_at": now_iso2,
                        "updated_at": now_iso2,
                    }
                assets.append(asset_row)
                existing_index[k] = asset_row

        _save("figma_rendered_assets.json", assets)

        # Finalize job state based on asset outcomes (simulate fast completion)
        job_assets = [a for a in assets if a.get("render_job_id") == job_row["id"]]
        any_ok = any(a.get("status") == "available" for a in job_assets)
        any_err = any(a.get("status") == "error" for a in job_assets)
        # Transition queued -> running -> terminal, respecting lifecycle transitions
        # queued can go to running; running to succeeded/partially_succeeded/failed
        job_row["status"] = "running"
        job_row["updated_at"] = _now_iso()
        _save("figma_image_render_jobs.json", jobs)

        if any_ok and any_err:
            job_row["status"] = "partially_succeeded"
        elif any_ok and not any_err:
            job_row["status"] = "succeeded"
        else:
            job_row["status"] = "failed"
            job_row["error"] = {"code": "RENDER_FAILED", "message": "No assets could be rendered."}
        job_row["completed_at"] = _now_iso()
        job_row["updated_at"] = _now_iso()
        _save("figma_image_render_jobs.json", jobs)

    # ---- maintenance: expire assets whose source_url_expires_at is past ----
    now_dt = datetime.datetime.utcnow()
    any_asset_updates = False
    for a in assets:
        if a.get("figma_file_id") != figma_file_id:
            continue
        if a.get("status") != "available":
            continue
        exp_dt = _dt_parse(a.get("source_url_expires_at"))
        if exp_dt and exp_dt < now_dt:
            a["status"] = "expired"
            a["updated_at"] = _now_iso()
            any_asset_updates = True
    if any_asset_updates:
        _save("figma_rendered_assets.json", assets)

    # ---- fetch assets for job with pagination ----
    if assets_limit is None:
        assets_limit = 100

    # cursor: accept opaque strings; if it matches an asset id in this job, start after it; else treat as offset cursor if base64 o:<n>
    def _cursor_to_start(cur):
        if cur is None:
            return 0
        # try asset id cursor
        idx_map = {}
        job_assets_sorted = []
        for a in assets:
            if a.get("render_job_id") == job_row.get("id"):
                job_assets_sorted.append(a)
        job_assets_sorted.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))
        for i, a in enumerate(job_assets_sorted):
            idx_map[a.get("id")] = i
        if cur in idx_map:
            return idx_map[cur] + 1
        # try offset base64 cursor
        if isinstance(cur, str):
            try:
                pad = "=" * (-len(cur) % 4)
                raw = base64.urlsafe_b64decode(cur + pad).decode("utf-8")
                if raw.startswith("o:"):
                    off = int(raw.split(":", 1)[1])
                    if off >= 0:
                        return off
            except Exception:
                return 0
        return 0

    def _make_offset_cursor(off):
        raw = f"o:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    job_assets_all = [a for a in assets if a.get("render_job_id") == job_row.get("id")]
    job_assets_all.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""))

    start = _cursor_to_start(assets_cursor)
    if start < 0:
        start = 0
    page = job_assets_all[start:start + assets_limit]
    next_cursor = None
    has_more = start + assets_limit < len(job_assets_all)
    if has_more:
        # use stable cursor: last returned asset id
        last_id = page[-1].get("id") if page else None
        next_cursor = last_id or _make_offset_cursor(start + assets_limit)

    # wait_for_completion: since we simulate completion on creation, only matters when polling existing job
    if wait_for_completion:
        # block briefly if non-terminal; don't spin long offline
        terminal = {"succeeded", "partially_succeeded", "failed", "cancelled"}
        if job_row.get("status") not in terminal:
            # attempt a short poll window
            deadline = time.time() + 2.0
            while time.time() < deadline:
                jobs2 = _load("figma_image_render_jobs.json")
                if isinstance(jobs2, list):
                    for j in jobs2:
                        if j.get("id") == job_row.get("id"):
                            job_row = j
                            break
                if job_row.get("status") in terminal:
                    break
                time.sleep(0.1)

    out = {
        "render_job": job_row,
        "assets": page,
        "pagination": {
            "total": len(job_assets_all),
            "limit": assets_limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        }
    }

    _reqlog("ok", (time.time() - t0) * 1000, extra={"render_job_id": job_row.get("id"), "created_job": created_job})
    return out

def list_figma_files(team_id=None, project_id=None, figma_file_key=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_figma_files"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        b = ts.to_bytes(6, "big") + os.urandom(10)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out))

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode(cur + pad).decode("utf-8")
            if not raw.startswith("o:"):
                return None
            off = int(raw.split(":", 1)[1])
            return off if off >= 0 else None
        except Exception:
            return None

    def _make_cursor(off):
        raw = f"o:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # request log + rate limit
    reqlog_name = "request_logs.json"
    reqlog = _load(reqlog_name)
    if not isinstance(reqlog, list):
        reqlog = []
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in reqlog[-2000:]:
        try:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            if dt >= window_start:
                recent += 1
        except Exception:
            continue
    RATE_LIMIT_PER_MIN = 240
    if recent >= RATE_LIMIT_PER_MIN:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("RATE_LIMIT", "Too many requests. Please slow down.", limit_per_minute=RATE_LIMIT_PER_MIN)

    # validate
    if team_id is not None and (not isinstance(team_id, str) or not team_id):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "team_id must be a non-empty string.", field="team_id")
    if project_id is not None and (not isinstance(project_id, str) or not project_id):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.", field="project_id")
    if figma_file_key is not None and (not isinstance(figma_file_key, str) or not figma_file_key):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "figma_file_key must be a non-empty string.", field="figma_file_key")

    allowed_status = {"active", "needs_auth", "error", "archived"}
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(x, str) or x not in allowed_status) for x in status):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("VALIDATION_ERROR", "status must be an array of valid statuses.", field="status", allowed=sorted(list(allowed_status)))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    off = _parse_cursor(cursor)
    if off is None:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    allowed_sort = {"created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc", "last_synced_at_asc", "last_synced_at_desc", "name_asc", "name_desc"}
    if sort is None:
        sort = "updated_at_desc"
    if not isinstance(sort, str) or sort not in allowed_sort:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "sort must be one of the supported sort values.", field="sort", allowed=sorted(list(allowed_sort)))

    files = _load("figma_files.json")
    if not isinstance(files, list):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("CONFLICT", "Datastore is corrupted or in an unexpected format.")

    rows = [f for f in files if isinstance(f, dict)]
    if team_id is not None:
        rows = [f for f in rows if f.get("team_id") == team_id]
    if project_id is not None:
        rows = [f for f in rows if f.get("project_id") == project_id]
    if figma_file_key is not None:
        rows = [f for f in rows if f.get("figma_file_key") == figma_file_key]
    if status is not None and len(status) > 0:
        sset = set(status)
        rows = [f for f in rows if f.get("status") in sset]

    def _s(v):
        return "" if v is None else (v.lower() if isinstance(v, str) else str(v))

    reverse = sort.endswith("_desc")
    if sort.startswith("created_at_"):
        keyf = lambda f: (_s(f.get("created_at")), _s(f.get("id")))
    elif sort.startswith("updated_at_"):
        keyf = lambda f: (_s(f.get("updated_at")), _s(f.get("id")))
    elif sort.startswith("last_synced_at_"):
        keyf = lambda f: (_s(f.get("last_synced_at")), _s(f.get("updated_at")), _s(f.get("id")))
    elif sort.startswith("name_"):
        keyf = lambda f: (_s(f.get("name")), _s(f.get("updated_at")), _s(f.get("id")))
    else:
        keyf = lambda f: (_s(f.get("updated_at")), _s(f.get("id")))

    rows.sort(key=keyf, reverse=reverse)

    total = len(rows)
    page = rows[off: off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "paging": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }

    reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
    _save(reqlog_name, reqlog)
    return resp

def upsert_figma_file(figma_file_key, name=None, team_id=None, project_id=None, status=None, auth_context_id=None, last_error=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "upsert_figma_file"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid_like(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        b = ts.to_bytes(6, "big") + os.urandom(10)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "".join(reversed(out))

    # request log + rate limit
    reqlog_name = "request_logs.json"
    reqlog = _load(reqlog_name)
    if not isinstance(reqlog, list):
        reqlog = []
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in reqlog[-2000:]:
        try:
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            if dt >= window_start:
                recent += 1
        except Exception:
            continue
    RATE_LIMIT_PER_MIN = 60
    if recent >= RATE_LIMIT_PER_MIN:
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("RATE_LIMIT", "Too many writes. Please slow down.", limit_per_minute=RATE_LIMIT_PER_MIN)

    # validate
    if not isinstance(figma_file_key, str) or not figma_file_key.strip():
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "figma_file_key must be a non-empty string.", field="figma_file_key")

    if name is not None and (not isinstance(name, str) or len(name) > 5000):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "name must be a string.", field="name")
    if team_id is not None and (not isinstance(team_id, str) or not team_id):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "team_id must be a non-empty string.", field="team_id")
    if project_id is not None and (not isinstance(project_id, str) or not project_id):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.", field="project_id")
    if auth_context_id is not None and (not isinstance(auth_context_id, str) or not auth_context_id):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "auth_context_id must be a non-empty string.", field="auth_context_id")
    if last_error is not None and not isinstance(last_error, str):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "last_error must be a string.", field="last_error")

    allowed_status = {"active", "needs_auth", "error", "archived"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "status must be one of the allowed values.", field="status", allowed=sorted(list(allowed_status)))

    files_name = "figma_files.json"
    files = _load(files_name)
    if not isinstance(files, list):
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
        _save(reqlog_name, reqlog)
        return _err("CONFLICT", "Datastore is corrupted or in an unexpected format.")

    existing = None
    for f in files:
        if isinstance(f, dict) and f.get("figma_file_key") == figma_file_key:
            existing = f
            break

    ts = _now_iso()

    if existing is None:
        # unique(figma_file_key)
        if any(isinstance(f, dict) and f.get("figma_file_key") == figma_file_key for f in files):
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "CONFLICT", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso()})
            _save(reqlog_name, reqlog)
            return _err("CONFLICT", "figma_file_key already exists.", figma_file_key=figma_file_key)

        row = {
            "id": _ulid_like("ffile_"),
            "figma_file_key": figma_file_key,
            "name": name if name is not None else None,
            "team_id": team_id if team_id is not None else None,
            "project_id": project_id if project_id is not None else None,
            "last_synced_at": None,
            "last_modified_at_remote": None,
            "status": status if status is not None else "active",
            "auth_context_id": auth_context_id if auth_context_id is not None else None,
            "last_error": {"message": last_error} if last_error is not None else None,
            "created_at": ts,
            "updated_at": ts,
        }
        files.append(row)
        _save(files_name, files)

        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "figma_file_id": row.get("id")})
        _save(reqlog_name, reqlog)
        return {"figma_file": row, "created": True}

    # updates
    old_status = existing.get("status")
    new_status = status if status is not None else old_status

    # disallow unarchive per tool description
    if old_status == "archived" and new_status != "archived":
        reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "figma_file_id": existing.get("id")})
        _save(reqlog_name, reqlog)
        return _err("VALIDATION_ERROR", "Cannot unarchive an archived file.", field="status", current=old_status, attempted=new_status)

    # lifecycle transitions
    transitions = {
        "active": {"error", "needs_auth", "archived"},
        "needs_auth": {"active", "archived"},
        "error": {"active", "needs_auth", "archived"},
        "archived": set(),
    }
    if new_status != old_status:
        allowed = transitions.get(old_status, set())
        if new_status not in allowed:
            reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "INVALID_TRANSITION", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "figma_file_id": existing.get("id")})
            _save(reqlog_name, reqlog)
            return _err("INVALID_TRANSITION", "Illegal status transition for figma file.", from_status=old_status, to_status=new_status)

    # apply updates
    if name is not None:
        existing["name"] = name
    if team_id is not None:
        existing["team_id"] = team_id
    if project_id is not None:
        existing["project_id"] = project_id
    if auth_context_id is not None:
        existing["auth_context_id"] = auth_context_id
    if status is not None:
        existing["status"] = status
    if last_error is not None:
        existing["last_error"] = {"message": last_error}
    # if status is active, clear last_error only if caller explicitly cleared (not supported), so leave as-is
    existing["updated_at"] = ts

    _save(files_name, files)

    reqlog.append({"id": _ulid_like("rlog_"), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "timestamp": _now_iso(), "figma_file_id": existing.get("id")})
    _save(reqlog_name, reqlog)
    return {"figma_file": dict(existing), "created": False}

def update_figma_file_status(figma_file_id, status, last_error=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Minimal request log mechanics: best-effort, only if collection exists in datastore.
    def _log(endpoint, status_code, latency_ms, detail=None):
        logs_name_candidates = [
            "request_logs.json",
            "usage_logs.json",
            "audit_logs.json",
            "api_requests.json",
        ]
        existing = None
        for fn in logs_name_candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if not existing:
            return
        logs = _load(existing)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(existing, logs)

    t0 = time.time()

    try:
        if not isinstance(figma_file_id, str) or not re.match(r"^ffile_[0-9A-HJKMNP-TV-Z]{10,}$", figma_file_id):
            out = _err("VALIDATION_ERROR", "figma_file_id is invalid.")
            _log("update_figma_file_status", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        allowed = {"active", "needs_auth", "error", "archived"}
        if not isinstance(status, str) or status not in allowed:
            out = _err("VALIDATION_ERROR", "status is invalid.", allowed=list(sorted(allowed)))
            _log("update_figma_file_status", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        if last_error is not None and not isinstance(last_error, str):
            out = _err("VALIDATION_ERROR", "last_error must be a string when provided.")
            _log("update_figma_file_status", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        files = _load("figma_files.json")
        idx = next((i for i, r in enumerate(files) if r.get("id") == figma_file_id), None)
        if idx is None:
            out = _err("NOT_FOUND", "figma file not found.")
            _log("update_figma_file_status", "NOT_FOUND", int((time.time() - t0) * 1000), out["error"])
            return out

        row = files[idx]
        current = row.get("status")
        transitions = {
            "active": ["error", "needs_auth", "archived"],
            "needs_auth": ["active", "archived"],
            "error": ["active", "needs_auth", "archived"],
            "archived": [],
        }

        if current not in transitions:
            out = _err("VALIDATION_ERROR", "current file status is invalid in datastore.", current_status=current)
            _log("update_figma_file_status", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        if status == current:
            # Idempotent: return current row unchanged
            out = {"figma_file": row}
            _log("update_figma_file_status", "OK", int((time.time() - t0) * 1000))
            return out

        if status not in transitions[current]:
            out = _err(
                "INVALID_TRANSITION",
                f"Cannot transition figma_files.status from '{current}' to '{status}'.",
                from_status=current,
                to_status=status,
                allowed=transitions[current],
            )
            _log("update_figma_file_status", "INVALID_TRANSITION", int((time.time() - t0) * 1000), out["error"])
            return out

        # Business rule: "Refuses ... attempts to create new work for archived files (VALIDATION_ERROR)."
        # This endpoint doesn't create work; allow transition into archived, but forbid transitioning out anyway via lifecycle.
        # If transitioning into error without details, still allowed (details optional). If details provided outside error, ignore.
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row["status"] = status
        if status == "error":
            if last_error:
                row["last_error"] = {"message": last_error}
            else:
                # keep existing last_error if any, else set minimal object
                row["last_error"] = row.get("last_error") or {"message": "Unknown error"}
        else:
            # Clear last_error when leaving error state
            if current == "error":
                row["last_error"] = None

        row["updated_at"] = now
        files[idx] = row
        _save("figma_files.json", files)

        out = {"figma_file": row}
        _log("update_figma_file_status", "OK", int((time.time() - t0) * 1000))
        return out
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected server error.", detail=str(e))
        _log("update_figma_file_status", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
        return out

def list_figma_file_snapshots(figma_file_key=None, figma_file_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0514000" if __import__("os").path.isdir("./environment_mix/0514000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _log(endpoint, status_code, latency_ms, detail=None):
        logs_name_candidates = [
            "request_logs.json",
            "usage_logs.json",
            "audit_logs.json",
            "api_requests.json",
        ]
        existing = None
        for fn in logs_name_candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                existing = fn
                break
        if not existing:
            return
        logs = _load(existing)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(existing, logs)

    t0 = time.time()

    def _parse_cursor(cur):
        # Cursor encodes an integer offset.
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    try:
        if figma_file_key is None and figma_file_id is None:
            out = _err("VALIDATION_ERROR", "Either figma_file_key or figma_file_id is required.")
            _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        if figma_file_key is not None and not isinstance(figma_file_key, str):
            out = _err("VALIDATION_ERROR", "figma_file_key must be a string.")
            _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        if figma_file_id is not None:
            if not isinstance(figma_file_id, str) or not re.match(r"^ffile_[0-9A-HJKMNP-TV-Z]{10,}$", figma_file_id):
                out = _err("VALIDATION_ERROR", "figma_file_id is invalid.")
                _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
                return out

        if status is not None:
            if not isinstance(status, list):
                out = _err("VALIDATION_ERROR", "status must be an array of snapshot statuses when provided.")
                _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
                return out
            allowed = {"queued", "building", "ready", "failed"}
            for s in status:
                if not isinstance(s, str) or s not in allowed:
                    out = _err("VALIDATION_ERROR", "status contains an invalid value.", allowed=list(sorted(allowed)))
                    _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
                    return out

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
            _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        if sort is None:
            sort = "created_at_desc"
        allowed_sort = {
            "created_at_asc",
            "created_at_desc",
            "build_started_at_asc",
            "build_started_at_desc",
            "build_completed_at_asc",
            "build_completed_at_desc",
        }
        if not isinstance(sort, str) or sort not in allowed_sort:
            out = _err("VALIDATION_ERROR", "sort is invalid.", allowed=list(sorted(allowed_sort)))
            _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        off = _parse_cursor(cursor)
        if off is None:
            out = _err("VALIDATION_ERROR", "cursor is invalid.")
            _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
            return out

        files = _load("figma_files.json")
        file_row = None
        if figma_file_id is not None:
            file_row = next((r for r in files if r.get("id") == figma_file_id), None)
        else:
            file_row = next((r for r in files if r.get("figma_file_key") == figma_file_key), None)

        # Listing snapshots for a non-existent file: NOT_FOUND is appropriate because file is the parent resource.
        if not file_row:
            out = _err("NOT_FOUND", "figma file not found.")
            _log("list_figma_file_snapshots", "NOT_FOUND", int((time.time() - t0) * 1000), out["error"])
            return out

        ffid = file_row.get("id")
        snaps = [s for s in _load("figma_file_snapshots.json") if s.get("figma_file_id") == ffid]

        if status is not None:
            wanted = set(status)
            snaps = [s for s in snaps if s.get("status") in wanted]

        def _key_field(row, field):
            v = row.get(field)
            return v if isinstance(v, str) and v else ""

        reverse = sort.endswith("_desc")
        if sort.startswith("created_at_"):
            snaps.sort(key=lambda r: _key_field(r, "created_at"), reverse=reverse)
        elif sort.startswith("build_started_at_"):
            snaps.sort(key=lambda r: (_key_field(r, "build_started_at"), _key_field(r, "created_at")), reverse=reverse)
        elif sort.startswith("build_completed_at_"):
            snaps.sort(key=lambda r: (_key_field(r, "build_completed_at"), _key_field(r, "created_at")), reverse=reverse)

        total = len(snaps)
        page = snaps[off:off + limit]
        next_off = off + len(page)
        has_more = next_off < total
        next_cursor = _make_cursor(next_off) if has_more else None

        out = {
            "snapshots": page,
            "pagination": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
            },
            "figma_file": {"id": ffid, "figma_file_key": file_row.get("figma_file_key")},
        }
        _log("list_figma_file_snapshots", "OK", int((time.time() - t0) * 1000))
        return out
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected server error.", detail=str(e))
        _log("list_figma_file_snapshots", "VALIDATION_ERROR", int((time.time() - t0) * 1000), out["error"])
        return out
